suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(readr);library(patchwork);library(ggrastr)})
o<-normalizePath('8-Visualization/refinements/fig3_feature_row_20261103_v5');tt<-normalizePath('8-Visualization/refinements/fig3_manuscript_revision_20261103_v4/main/source_data');ff<-file.path(o,'figures');rd<-function(n)read_csv(file.path(tt,n),show_col_types=FALSE)
studycols<-read_csv('0-Data/qc/study_color_dictionary.csv',show_col_types=FALSE)
emit<-function(p,n,w,h){saveRDS(p,file.path(ff,paste0(n,'.rds')));svglite::svglite(file.path(ff,paste0(n,'.svg')),width=w/25.4,height=h/25.4);print(p);dev.off();cairo_pdf(file.path(ff,paste0(n,'.pdf')),width=w/25.4,height=h/25.4,family='Arial');print(p);dev.off();ragg::agg_png(file.path(ff,paste0(n,'.png')),width=w,height=h,units='mm',res=600,background='white');print(p);dev.off()}
f<-rd('featureplot_selected_cells.csv.gz');prs<-c('Pattern_P1','WGCNA_MEpink','Pattern_P3','WGCNA_MEbrown','Pattern_P6','WGCNA_MEred');short<-c(Pattern_P1='P1',WGCNA_MEpink='pink',Pattern_P3='P3',WGCNA_MEbrown='brown',Pattern_P6='P6',WGCNA_MEred='red')
feature<-function(pr){dd<-f%>%mutate(Value=.data[[pr]])%>%arrange(Value);ggplot(dd,aes(UMAP1,UMAP2))+geom_point_rast(colour='#DEDEDE',size=.10,raster.dpi=600)+geom_point_rast(data=filter(dd,!is.na(Value)),aes(colour=Value),size=.10,raster.dpi=600)+scale_colour_gradientn(colours=c('#E7E7E7','#8FC4C8','#317F8C','#123E50'),limits=range(dd$Value,na.rm=TRUE),breaks=scales::pretty_breaks(n=2),name='UCell')+coord_equal(xlim=c(-10.8,22.1),ylim=c(-13.2,20),expand=FALSE)+labs(title=short[pr])+theme_void(base_family='Arial',base_size=5)+theme(plot.title=element_text(size=5.5,face='bold',hjust=.5),legend.position='bottom',legend.title=element_text(size=5),legend.text=element_text(size=5),legend.margin=margin(0,0,0,0),legend.box.spacing=grid::unit(0,'mm'),plot.margin=margin(0,1,0,1))+guides(colour=guide_colourbar(barwidth=grid::unit(18,'mm'),barheight=grid::unit(1.3,'mm'),title.position='top',title.hjust=.5))}
heads<-c('C1 context | P1–pink\n177 shared; 73% P1 / 66% pink','C2 context | P3–brown\n101 shared; 65% P3 / 21% brown','C3 context | P6–red\n65 shared; 71% P6 / 21% red')
headers<-lapply(heads,function(h)wrap_elements(full=grid::textGrob(h,gp=grid::gpar(fontfamily='Arial',fontsize=5.6,fontface='bold',lineheight=1.1))))
pc<-wrap_plots(c(headers,lapply(prs,feature)),design='AABBCC\nDEFGHI',heights=c(6,36))+plot_annotation(title='Overlap-guided pattern–module pairs across the three bulk contexts',theme=theme(plot.title=element_text(size=6.5,face='bold'),plot.margin=margin(2,1,1,8)))
emit(pc,'Figure3C_six_in_one_row',174,48)
